/**
 * Applies the custom vocabulary pack to the page for chosen, signed-in people, and lets managers drop a new pack
 * anywhere on the site.
 *
 * @module     local_materialtools/vocabulary
 * @copyright  2026 Ding Ding Projects
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define('local_materialtools/vocabulary', [], function() {
    var SKIP = {SCRIPT: 1, STYLE: 1, TEXTAREA: 1, INPUT: 1, CODE: 1, PRE: 1, KBD: 1, SAMP: 1, NOSCRIPT: 1, SELECT: 1, OPTION: 1};
    var ATTRS = ['placeholder', 'title', 'aria-label', 'alt'];
    var map = null;
    var pattern = null;

    /**
     * Escape text for a regular expression.
     *
     * @param {string} s
     * @returns {string}
     */
    function esc(s) {
        return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    }

    /**
     * Replacement that keeps a capital first letter when the original had one.
     *
     * @param {string} found
     * @returns {string}
     */
    function swap(found) {
        var value = map[found.toLowerCase()];
        if (value === undefined) {
            return found;
        }
        var first = found.charAt(0);
        if (first !== first.toLowerCase() && value.charAt(0) === value.charAt(0).toLowerCase()) {
            return value.charAt(0).toUpperCase() + value.slice(1);
        }
        return value;
    }

    /**
     * Rewrite the words under a node.
     *
     * @param {Node} root
     */
    function apply(root) {
        if (!pattern || !root) {
            return;
        }
        if (root.nodeType === 3) {
            if (root.parentNode && !SKIP[root.parentNode.nodeName] && pattern.test(root.nodeValue)) {
                pattern.lastIndex = 0;
                root.nodeValue = root.nodeValue.replace(pattern, swap);
            }
            pattern.lastIndex = 0;
            return;
        }
        if (root.nodeType !== 1 || SKIP[root.nodeName] || root.isContentEditable || root.closest('[data-vocab-skip]')) {
            return;
        }
        ATTRS.forEach(function(a) {
            var v = root.getAttribute(a);
            if (v) {
                root.setAttribute(a, v.replace(pattern, swap));
            }
        });
        var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT, {
            acceptNode: function(n) {
                if (n.nodeType === 1) {
                    if (SKIP[n.nodeName] || n.isContentEditable || n.hasAttribute('data-vocab-skip')) {
                        return NodeFilter.FILTER_REJECT;
                    }
                    ATTRS.forEach(function(a) {
                        var v = n.getAttribute(a);
                        if (v) {
                            n.setAttribute(a, v.replace(pattern, swap));
                        }
                    });
                    return NodeFilter.FILTER_SKIP;
                }
                return NodeFilter.FILTER_ACCEPT;
            }
        });
        var nodes = [];
        while (walker.nextNode()) {
            nodes.push(walker.currentNode);
        }
        nodes.forEach(function(t) {
            var next = t.nodeValue.replace(pattern, swap);
            if (next !== t.nodeValue) {
                t.nodeValue = next;
            }
        });
    }

    /**
     * Load the pack and start rewriting.
     *
     * @param {string} url
     */
    function start(url) {
        fetch(url, {credentials: 'same-origin'}).then(function(r) {
            return r.ok ? r.json() : {entries: {}};
        }).then(function(data) {
            var keys = Object.keys(data.entries || {});
            if (!keys.length) {
                return null;
            }
            map = {};
            keys.forEach(function(k) {
                map[k.toLowerCase()] = data.entries[k];
            });
            keys.sort(function(a, b) {
                return b.length - a.length;
            });
            pattern = new RegExp('(?<![\\p{L}\\p{N}])(?:' + keys.map(esc).join('|') + ')(?![\\p{L}\\p{N}])', 'giu');
            apply(document.body);
            document.title = document.title.replace(pattern, swap);
            var pending = [];
            var timer = null;
            new MutationObserver(function(records) {
                records.forEach(function(r) {
                    if (r.type === 'characterData') {
                        pending.push(r.target);
                    } else {
                        r.addedNodes.forEach(function(n) {
                            pending.push(n);
                        });
                    }
                });
                if (!timer) {
                    timer = setTimeout(function() {
                        var batch = pending;
                        pending = [];
                        timer = null;
                        batch.forEach(apply);
                    }, 30);
                }
            }).observe(document.body, {childList: true, subtree: true, characterData: true});
            return null;
        }).catch(function() {
            // The original wording stays when the pack cannot be loaded.
            return null;
        });
    }

    /**
     * Managers can drop a pack anywhere.
     *
     * @param {Object} config
     */
    function dropzone(config) {
        var s = config.strings || {};
        var isFile = function(e) {
            return e.dataTransfer && Array.prototype.indexOf.call(e.dataTransfer.types || [], 'Files') !== -1;
        };
        document.addEventListener('dragover', function(e) {
            if (isFile(e)) {
                e.preventDefault();
            }
        });
        document.addEventListener('drop', function(e) {
            if (!isFile(e) || e.target.closest('input[type=file], .filemanager, .dndupload-target, [data-region="vocab-drop"]')) {
                return;
            }
            var file = e.dataTransfer.files[0];
            if (!file || !/\.json$/i.test(file.name)) {
                return;
            }
            e.preventDefault();
            file.text().then(function(text) {
                return fetch(config.drop, {method: 'POST', credentials: 'same-origin',
                    headers: {'Content-Type': 'application/json'}, body: text});
            }).then(function(r) {
                return r.json();
            }).then(function(result) {
                announce(result.success ? (result.headline || s.vocabapplied) :
                    (s.dropinvalid || '{$a}').replace('{$a}', result.error || ''), result.success);
                if (result.success) {
                    setTimeout(function() {
                        window.location.reload();
                    }, 3200);
                }
                return null;
            }).catch(function() {
                return null;
            });
        });
    }

    /**
     * Full-window headline that animates in, holds and leaves.
     *
     * @param {string} text
     * @param {boolean} good
     */
    function announce(text, good) {
        var box = document.createElement('div');
        box.setAttribute('role', good ? 'status' : 'alert');
        box.className = 'local-materialtools-levelup ' + (good ? 'is-good' : 'is-bad');
        box.textContent = text;
        document.body.appendChild(box);
        require(['theme_material/celebrate'], function(C) {
            if (good) {
                C.burst();
            } else {
                C.failure(box);
            }
        }, function() {
            return null;
        });
        setTimeout(function() {
            box.classList.add('is-leaving');
        }, 3000);
        setTimeout(function() {
            box.remove();
        }, 3600);
    }

    return {
        /**
         * Start.
         *
         * @param {Object} config {url, drop, strings}
         */
        init: function(config) {
            if (config.url) {
                start(config.url);
            }
            if (config.drop) {
                dropzone(config);
            }
        },
        announce: announce
    };
});
